<?php
declare(strict_types=1);
$env=[];foreach(file(__DIR__.'/../.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $l){$l=trim($l);if($l===''||$l[0]==='#'||!str_contains($l,'='))continue;[$k,$v]=explode('=',$l,2);$env[trim($k)]=trim(trim($v),"\"'");}
$o=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC];$s=new PDO('mysql:host='.$env['LEGADO_SEGURANCA_DB_HOST'].';port='.$env['LEGADO_SEGURANCA_DB_PORT'].';dbname=green_atlas_seguranca;charset=utf8mb4',$env['LEGADO_SEGURANCA_DB_USERNAME'],$env['LEGADO_SEGURANCA_DB_PASSWORD'],$o);$t=new PDO('mysql:host='.$env['GPT_DB_HOST'].';port='.$env['GPT_DB_PORT'].';dbname=gatlas_dbp;charset=utf8mb4',$env['GPT_DB_USERNAME'],$env['GPT_DB_PASSWORD'],$o);
$map=['ADMINISTRADOR'=>'ADMINISTRADOR','ADM DA EMPRESA'=>'ADM_DA_EMPRESA','FORNECEDOR'=>'FORNECEDOR'];$groups=$s->query('SELECT CODGRUPO,DSCGRUPO FROM grupos')->fetchAll();$changed=[];$mapped=0;
foreach($groups as $g){$legacy=(string)$g['DSCGRUPO'];if(!isset($map[$legacy]))continue;$code=$map[$legacy];$q=$t->prepare('SELECT codperfil FROM perfis WHERE codigo=? LIMIT 1');$q->execute([$code]);$profile=(int)$q->fetchColumn();if(!$profile)throw new RuntimeException("Perfil oficial nao encontrado: $code");$t->prepare('UPDATE atlas_perfis_legado SET codperfil=?,descricao=? WHERE codgrupo=?')->execute([$profile,$legacy,(int)$g['CODGRUPO']]);$t->prepare('UPDATE perfis SET nome=?,ativo=1 WHERE codperfil=?')->execute([$legacy,$profile]);$duplicate='ATLAS_GRUPO_'.(int)$g['CODGRUPO'];if($duplicate!==$code)$t->prepare('UPDATE perfis SET ativo=0 WHERE codigo=? AND codperfil<>?')->execute([$duplicate,$profile]);$changed[]=['codgrupo'=>(int)$g['CODGRUPO'],'grupo'=>$legacy,'codperfil'=>$profile,'perfil'=>$code];$mapped++;}
$adminGroup=(int)$s->query("SELECT CODGRUPO FROM grupos WHERE DSCGRUPO='ADMINISTRADOR' LIMIT 1")->fetchColumn();$userRows=$s->query('SELECT CODUSUARIO,CODGRUPO FROM usuariosxgrupos ORDER BY CODUSUARIO')->fetchAll();$byUser=[];foreach($userRows as $r)$byUser[(int)$r['CODUSUARIO']][]=(int)$r['CODGRUPO'];$assigned=0;$adminUsers=0;foreach($byUser as $user=>$groupsForUser){$groupsForUser=array_values(array_unique($groupsForUser));$profile=null;if($adminGroup&&in_array($adminGroup,$groupsForUser,true)){$q=$t->query("SELECT codperfil FROM perfis WHERE codigo='ADMINISTRADOR'");$profile=(int)$q->fetchColumn();$adminUsers++;}elseif(count($groupsForUser)===1){$q=$t->prepare('SELECT codperfil FROM atlas_perfis_legado WHERE codgrupo=?');$q->execute([$groupsForUser[0]]);$profile=(int)$q->fetchColumn();}if($profile){$t->prepare("UPDATE usuarios SET codperfil=? WHERE codusuario=? AND userid<>'admin'")->execute([$profile,$user]);$t->prepare('UPDATE atlas_usuarios_perfis_legado SET codperfil=?,efetivo=0 WHERE codusuario=?')->execute([$profile,$user]);$assigned++;}}
$detail=['equivalencias'=>$changed,'usuarios_atribuidos'=>$assigned,'usuarios_administrador'=>$adminUsers,'regra'=>'grupo ADMINISTRADOR sempre usa perfil ADMINISTRADOR','perfis_redundantes_inativados'=>true];$q=$t->prepare("INSERT INTO registros_migracao (codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES ('ATLAS_PERFIS_EQUIVALENTES','green_atlas_seguranca.grupos;usuariosxgrupos','gatlas_dbp.perfis;usuarios','DADOS','0.160.0','CONCLUIDA',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)");$q->execute([$assigned,json_encode($detail,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);echo json_encode($detail,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
